export function getOctober2026OfficialBeatSchedule(beatNo: string): FuelDailyRow[] | undefined {
  const numMatch = (beatNo || '').match(/\d+/);
  if (!numMatch) return undefined;
  const seq = parseInt(numMatch[0], 10);
  const rows = OCTOBER_2026_ALL_33_BEATS_SCHEDULE[seq];
  return rows ? rows.map((r) => ({ ...r })) : undefined;
}

export function getOctober2026BeatMeta(beatNo: string): October2026BeatMeta | undefined {
  const numMatch = (beatNo || '').match(/\d+/);
  if (!numMatch) return undefined;
  const seq = parseInt(numMatch[0], 10);
  return OCTOBER_2026_BEAT_METADATA[seq];
}
